package com.zhou.craft.service;
import com.zhou.craft.dto.ShipForm;import com.zhou.craft.model.*;import com.zhou.craft.repo.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class MockLogisticsService implements LogisticsService{
private final ShipmentRepository shipments;private final LogisticsTraceRepository traces;private final CraftOrderRepository orders;public MockLogisticsService(ShipmentRepository s,LogisticsTraceRepository t,CraftOrderRepository o){shipments=s;traces=t;orders=o;}
@Transactional public Shipment ship(CraftOrder order,ShipForm f){if(shipments.findByOrderId(order.getId()).isPresent())throw new IllegalStateException("该订单已创建物流单");String carrier=f==null||f.carrier()==null||f.carrier().isBlank()?"顺丰速运（模拟）":f.carrier();String no=f==null||f.trackingNo()==null||f.trackingNo().isBlank()?"MOCK"+System.currentTimeMillis():f.trackingNo();order.markShipped();orders.save(order);var s=shipments.save(new Shipment(order.getId(),carrier,no));traces.save(new LogisticsTrace(s.getId(),"已发货","南昌创作者工作室","创作者已完成打包并提交物流信息"));return s;}
@Transactional public Shipment advance(CraftOrder order){var s=shipments.findByOrderId(order.getId()).orElseThrow(()->new IllegalStateException("物流单不存在"));if("已发货".equals(s.getStatus())){s.inTransit();order.markInTransit();traces.save(new LogisticsTrace(s.getId(),"运输中","南昌转运中心","包裹已揽收并发往目的地转运中心"));}else if("运输中".equals(s.getStatus())){s.delivered();order.markDelivered();traces.save(new LogisticsTrace(s.getId(),"已签收","收货地址","快件已签收，等待用户验收定制作品"));}else throw new IllegalStateException("当前物流状态无需继续推进");orders.save(order);return shipments.save(s);}
public Optional<Shipment> findByOrderId(Long orderId){return shipments.findByOrderId(orderId);}public List<LogisticsTrace> traces(Long shipmentId){return traces.findByShipmentIdOrderByOccurredAtAsc(shipmentId);}
}